package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class LiveDataActivity extends Activity{private final Handler ui=new Handler(Looper.getMainLooper());private LinearLayout results;private TextView status;private EventMapView map;
private static final String[][] MAP_SOURCES={{"sit-quebec-evenements","SIT Québec"},{"vmtl-evenements-publics","Ville de Montréal"},{"sit-quebec-culture-art-et-patrimoine","SIT Québec — culture/patrimoine"},{"sites-patrimoniaux-declares-par-le-gouvernement-du-quebec","Québec — sites patrimoniaux déclarés"},{"sites-patrimoniaux-classes-par-la-ministre-de-la-culture-et-des-communications","Québec — sites patrimoniaux classés"},{"immeubles-patrimoniaux-classes-par-la-ministre-de-la-culture-et-des-communications","Québec — immeubles patrimoniaux classés"},{"sites-patrimoniaux-cites-par-les-municipalites-et-les-communautes-autochtones","Municipalités et communautés autochtones — sites cités"},{"immeubles-patrimoniaux-cites-par-les-municipalites-et-les-communautes-autochtones","Municipalités et communautés autochtones — immeubles cités"}};
@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Données culturelles en direct",28,true));r.addView(Ui.text(this,"Données publiques du Québec interprétées en fiches et, lorsque les coordonnées existent, placées sur une carte tactile. Aucune coordonnée n’est inventée.",14,false));LinearLayout mp=Ui.panel(this);mp.addView(Ui.text(this,"Carte culturelle et historique interactive du Québec",21,true));map=new EventMapView(this);mp.addView(map,new LinearLayout.LayoutParams(-1,Ui.dp(this,560)));Button refresh=Ui.secondary(this,"↻ Actualiser toutes les sources");refresh.setOnClickListener(v->refreshMap());mp.addView(refresh);r.addView(mp);LinearLayout choices=Ui.panel(this);Button e=Ui.secondary(this,"📅 Événements — tout le Québec");e.setOnClickListener(v->load("sit-quebec-evenements","Événements SIT Québec"));choices.addView(e);Button c=Ui.secondary(this,"🏛 Culture, arts et patrimoine");c.setOnClickListener(v->load("sit-quebec-culture-art-et-patrimoine","Culture, arts et patrimoine"));choices.addView(c);Button m=Ui.secondary(this,"📍 Événements publics de Montréal");m.setOnClickListener(v->load("vmtl-evenements-publics","Événements publics de Montréal"));choices.addView(m);Button h=Ui.secondary(this,"🏰 Sites historiques et patrimoniaux");h.setOnClickListener(v->refreshMap());choices.addView(h);Button fed=Ui.secondary(this,"🇨🇦 Lieux historiques nationaux — Québec");fed.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.pc.gc.ca/apps/dfhd/search-recherche_fra.aspx")));}catch(Exception ignored){}});choices.addView(fed);r.addView(choices);status=Ui.text(this,"Chargement…",14,false);r.addView(status);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);r.addView(results);setContentView(Ui.wrap(this,r));refreshMap();load("sit-quebec-evenements","Événements SIT Québec");}
private void refreshMap(){status.setText("Actualisation culture + patrimoine…");new Thread(()->{ArrayList<JSONObject> all=new ArrayList<>();int n=0;for(String[] s:MAP_SOURCES)try{all.addAll(fetchAny(s[0],s[1].startsWith("SIT")?250:300,s[1]));n++;}catch(Exception ignored){}int count=n;ui.post(()->{map.setRecords(all,"Données Québec");status.setText(count+" source(s) actualisée(s) · "+all.size()+" fiche(s) analysée(s) · patrimoine provincial et municipal inclus");});}).start();}
private void load(String id,String title){status.setText("Chargement de "+title+"…");new Thread(()->{try{ArrayList<JSONObject> rows=fetchAny(id,100,title);ui.post(()->render(title,rows));}catch(Exception ex){ui.post(()->status.setText("Chargement impossible : "+ex.getMessage()));}}).start();}
private ArrayList<JSONObject> fetchAny(String id,int limit,String src)throws Exception{ArrayList<JSONObject> out=new ArrayList<>();String p="https://www.donneesquebec.ca/recherche/api/3/action/package_show?id="+URLEncoder.encode(id,"UTF-8");JSONObject pkg=new JSONObject(get(p)).getJSONObject("result");JSONArray resources=pkg.optJSONArray("resources");JSONObject ds=null,geo=null,csv=null;if(resources!=null)for(int i=0;i<resources.length();i++){JSONObject x=resources.optJSONObject(i);if(x==null)continue;String f=x.optString("format","").toLowerCase(Locale.ROOT);if(x.optBoolean("datastore_active",false)&&ds==null)ds=x;if(f.contains("geojson")&&geo==null)geo=x;if(f.equals("csv")&&csv==null)csv=x;}if(ds!=null){String u="https://www.donneesquebec.ca/recherche/api/3/action/datastore_search?resource_id="+URLEncoder.encode(ds.optString("id"),"UTF-8")+"&limit="+limit;JSONArray a=new JSONObject(get(u)).getJSONObject("result").optJSONArray("records");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null){x.put("_map_source",src);out.add(x);}}return out;}if(geo!=null){JSONObject g=new JSONObject(get(geo.optString("url")));JSONArray a=g.optJSONArray("features");if(a!=null)for(int i=0;i<Math.min(limit,a.length());i++){JSONObject f=a.optJSONObject(i);if(f==null)continue;JSONObject x=f.optJSONObject("properties");if(x==null)x=new JSONObject();JSONObject geometry=f.optJSONObject("geometry");if(geometry!=null){JSONArray co=geometry.optJSONArray("coordinates");String type=geometry.optString("type");if("Point".equalsIgnoreCase(type)&&co!=null&&co.length()>=2){x.put("longitude",co.optDouble(0));x.put("latitude",co.optDouble(1));}}x.put("_map_source",src);out.add(x);}return out;}return out;}
private void render(String title,List<JSONObject> rows){results.removeAllViews();status.setText(rows.size()+" fiche(s) — "+title);ArrayList<JSONObject> sorted=new ArrayList<>(rows);sorted.sort(Comparator.comparing(this::dateKey).thenComparing(this::title,String.CASE_INSENSITIVE_ORDER));for(JSONObject o:sorted){LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,title(o),18,true));String d=date(o),place=first(o,"Lieu","lieu","Ville","ville","municipalite","Municipalite","adresse","Adresse");if(!d.isEmpty())p.addView(Ui.text(this,"📅 "+d,14,false));if(!place.isEmpty())p.addView(Ui.text(this,"📍 "+place,14,false));String type=first(o,"type","Type","categorie","Categorie","Theme","theme","genre","Genre","Statut","statut","TYPE_STATUT");if(!type.isEmpty())p.addView(Ui.text(this,type,13,false));String url=url(o);if(!url.isEmpty()){Button b=Ui.secondary(this,"Plus d’info");b.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception ignored){}});p.addView(b);}p.addView(Ui.text(this,"Source : "+first(o,"_map_source"),11,false));results.addView(p);}}
private String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("User-Agent","CultureDuQuebec/3.9");try(InputStream in=c.getInputStream()){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}finally{c.disconnect();}}
private String first(JSONObject o,String...ks){for(String k:ks){Object v=o.opt(k);if(v!=null&&!JSONObject.NULL.equals(v)){String s=String.valueOf(v).replaceAll("<[^>]*>"," ").trim();if(!s.isEmpty()&&!"null".equalsIgnoreCase(s))return s;}}return"";}private String title(JSONObject o){String s=first(o,"NomEtablissement","titre","Titre","nom","Nom","NOM","name","Name","evenement","Evenement","NOM_BIEN","nom_bien");return s.isEmpty()?"Fiche culturelle ou patrimoniale":s;}private String date(JSONObject o){return first(o,"DateDebut","dateDebut","date_debut","date","Date","start_date","startDate","debut","DateStatut","DATE_STATUT");}private String dateKey(JSONObject o){String s=date(o);java.util.regex.Matcher m=java.util.regex.Pattern.compile("(\\d{4})[-/](\\d{1,2})[-/](\\d{1,2})").matcher(s);if(m.find())return String.format(java.util.Locale.ROOT,"%s%02d%02d",m.group(1),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3)));return"99999999";}private String url(JSONObject o){Iterator<String>it=o.keys();while(it.hasNext()){String k=it.next();String n=k.toLowerCase(java.util.Locale.ROOT);if(n.contains("url")||n.contains("site")||n.contains("lien")){String s=String.valueOf(o.opt(k));int i=s.indexOf("http");if(i>=0)return s.substring(i).split("[ \\\"<>]",2)[0];}}return"";}}
